use std::fs;
use std::path::{Path, PathBuf};

use base64::Engine;
use base64::engine::general_purpose::STANDARD as BASE64;
use ed25519_dalek::{Signer, SigningKey};
use forge::manifest::{
    UpdatePlatformEntry, canonical_update_signing_payload, current_updater_platform_key,
};
use sha2::{Digest, Sha256};

use crate::{CliError, Result};

/// Ed25519 keypair generated by `forge signer keygen`.
#[derive(Debug, Clone)]
pub struct GeneratedKeypair {
    /// Base64-encoded 32-byte Ed25519 secret seed (`0600` private key).
    pub secret_key_base64: String,
    /// Base64-encoded 32-byte Ed25519 verifying key for `[updater] pubkey = "..."`.
    pub public_key_base64: String,
}

#[derive(Debug, Clone)]
pub struct KeygenOptions {
    pub out_key_path: PathBuf,
    pub force: bool,
}

#[derive(Debug, Clone)]
pub struct KeygenOutput {
    pub secret_key_path: PathBuf,
    pub public_key_path: PathBuf,
    pub public_key_base64: String,
}

#[derive(Debug, Clone)]
pub struct SignArtifactOptions {
    pub artifact_path: PathBuf,
    pub secret_key_path: Option<PathBuf>,
    pub version: Option<String>,
    pub platform: Option<String>,
    pub download_url: Option<String>,
}

#[derive(Debug, Clone)]
pub struct SignArtifactOutput {
    pub sig_file_path: PathBuf,
    pub entry: UpdatePlatformEntry,
}

/// Generates a fresh CSPRNG-backed Ed25519 signing keypair.
pub fn generate_ed25519_keypair() -> Result<GeneratedKeypair> {
    let mut seed = [0u8; 32];
    getrandom::fill(&mut seed)
        .map_err(|e| CliError::InvalidArgument(format!("OS CSPRNG failed: {e}")))?;
    let signing_key = SigningKey::from_bytes(&seed);
    let verifying_key = signing_key.verifying_key();

    Ok(GeneratedKeypair {
        secret_key_base64: BASE64.encode(signing_key.to_bytes()),
        public_key_base64: BASE64.encode(verifying_key.to_bytes()),
    })
}

/// Writes an Ed25519 keypair to disk (`<out>.key` with `0600` permissions on Unix + `<out>.pub`).
pub fn run_keygen(opts: &KeygenOptions) -> Result<KeygenOutput> {
    if opts.out_key_path.exists() && !opts.force {
        return Err(CliError::InvalidArgument(format!(
            "key file '{}' already exists (pass --force to overwrite)",
            opts.out_key_path.display()
        )));
    }
    if let Some(parent) = opts.out_key_path.parent()
        && !parent.as_os_str().is_empty()
    {
        fs::create_dir_all(parent).map_err(|e| CliError::Io {
            path: parent.to_path_buf(),
            message: format!("failed to create key directory: {e}"),
        })?;
    }

    let kp = generate_ed25519_keypair()?;
    write_restricted_secret_file(&opts.out_key_path, &format!("{}\n", kp.secret_key_base64))?;

    let pub_path = PathBuf::from(format!("{}.pub", opts.out_key_path.display()));
    fs::write(&pub_path, format!("{}\n", kp.public_key_base64)).map_err(|e| CliError::Io {
        path: pub_path.clone(),
        message: format!("failed to write public key: {e}"),
    })?;

    Ok(KeygenOutput {
        secret_key_path: opts.out_key_path.clone(),
        public_key_path: pub_path,
        public_key_base64: kp.public_key_base64,
    })
}

/// Decodes a Base64 32-byte Ed25519 secret seed from raw text or file.
pub fn parse_signing_key(raw_b64: &str) -> Result<SigningKey> {
    let trimmed = raw_b64.trim();
    let decoded = BASE64.decode(trimmed).map_err(|e| {
        CliError::InvalidArgument(format!("invalid base64 Ed25519 signing key: {e}"))
    })?;
    let seed: [u8; 32] = decoded.try_into().map_err(|_| {
        CliError::InvalidArgument(
            "Ed25519 signing key must decode to exactly 32 secret seed bytes".into(),
        )
    })?;
    Ok(SigningKey::from_bytes(&seed))
}

/// Computes SHA-256 and produces a metadata-bound Ed25519 [`UpdatePlatformEntry`] for `artifact_path`.
pub fn sign_artifact_with_key(
    signing_key: &SigningKey,
    artifact_path: &Path,
    version: &str,
    platform: &str,
    download_url: &str,
) -> Result<UpdatePlatformEntry> {
    let bytes = fs::read(artifact_path).map_err(|e| CliError::Io {
        path: artifact_path.to_path_buf(),
        message: format!("failed to read artifact for signing: {e}"),
    })?;

    let mut hasher = Sha256::new();
    hasher.update(&bytes);
    let digest = hasher.finalize();
    let mut sha256_hex = String::with_capacity(64);
    for b in digest {
        use std::fmt::Write as _;
        let _ = write!(&mut sha256_hex, "{b:02x}");
    }

    let message = canonical_update_signing_payload(version, platform, download_url, &sha256_hex);
    let signature = signing_key.sign(&message);

    Ok(UpdatePlatformEntry {
        url: download_url.to_string(),
        sha256: sha256_hex,
        signature: BASE64.encode(signature.to_bytes()),
    })
}

/// Signs `artifact_path`, writes `<file>.sig` detached signature to disk, and returns its `latest.json` entry.
pub fn run_sign_artifact(opts: &SignArtifactOptions) -> Result<SignArtifactOutput> {
    let raw_key = match &opts.secret_key_path {
        Some(path) => fs::read_to_string(path).map_err(|e| CliError::Io {
            path: path.clone(),
            message: format!("failed to read signing key: {e}"),
        })?,
        None => std::env::var("FORGE_UPDATER_PRIVATE_KEY").map_err(|_| {
            CliError::InvalidArgument(
                "pass --key <path> or set FORGE_UPDATER_PRIVATE_KEY to sign an artifact".into(),
            )
        })?,
    };
    let signing_key = parse_signing_key(&raw_key)?;
    let platform = opts
        .platform
        .clone()
        .unwrap_or_else(current_updater_platform_key);
    let version = opts.version.clone().unwrap_or_else(|| "0.1.0".to_string());
    let file_name = opts
        .artifact_path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("artifact.bin");
    let download_url = opts
        .download_url
        .clone()
        .unwrap_or_else(|| format!("https://localhost/releases/v{version}/{file_name}"));

    let entry = sign_artifact_with_key(
        &signing_key,
        &opts.artifact_path,
        &version,
        &platform,
        &download_url,
    )?;

    let sig_file_path = PathBuf::from(format!("{}.sig", opts.artifact_path.display()));
    fs::write(&sig_file_path, format!("{}\n", entry.signature)).map_err(|e| CliError::Io {
        path: sig_file_path.clone(),
        message: format!("failed to write detached .sig file: {e}"),
    })?;

    Ok(SignArtifactOutput {
        sig_file_path,
        entry,
    })
}

fn write_restricted_secret_file(path: &Path, contents: &str) -> Result<()> {
    #[cfg(unix)]
    {
        use std::io::Write;
        use std::os::unix::fs::OpenOptionsExt;
        let mut f = fs::OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .mode(0o600)
            .open(path)
            .map_err(|e| CliError::Io {
                path: path.to_path_buf(),
                message: format!("failed to write secret key: {e}"),
            })?;
        f.write_all(contents.as_bytes()).map_err(|e| CliError::Io {
            path: path.to_path_buf(),
            message: format!("failed to write secret key: {e}"),
        })?;
        Ok(())
    }
    #[cfg(not(unix))]
    {
        fs::write(path, contents).map_err(|e| CliError::Io {
            path: path.to_path_buf(),
            message: format!("failed to write secret key: {e}"),
        })
    }
}
